#define SWAP(a, b)                                                                                 \
    do {                                                                                           \
        int *t = a;                                                                                \
        a = b;                                                                                     \
        b = t;                                                                                     \
    } while(0)

int *find(int *first, int *last, int value);

void exchange(int *x, int *y) {
    SWAP(x, y);
}

